import {bindProfilePhoto,profilePhotoPicker} from './profile-photo-picker.mjs';
import { t, translateError } from './i18n.mjs';
let api,success,stage='choose',login=false;
export function initBrosJoin(callbacks){api=callbacks;const root=document.createElement('section');root.id='bros-join';document.body.append(root);root.addEventListener('click',ev=>{const b=ev.target.closest('[data-bros]');if(!b)return;switch(b.dataset.bros){case 'back':if(stage==='choose'){document.body.classList.remove('bros-join-mode');api.back();}else{stage='choose';render();}break;case 'nickname':stage='nickname';login=false;render();break;case 'full':document.body.classList.remove('bros-join-mode');api.full(success);break;case 'login':login=!login;render();break;case 'password':{const field=document.querySelector('#bros-password');field.type=field.type==='password'?'text':'password';b.textContent=field.type==='password'?t("Show","Hiện","표시"):t("Hide","Ẩn","숨기기");break;}}});}
export async function showBrosJoin(callback){success=callback;try{const response=await fetch('/api/auth/me',{credentials:'same-origin'});const {user}=await response.json();if(response.ok&&user?.role==='Bros'){success(user);return;}}catch{}stage='choose';login=false;document.body.classList.remove('onboarding','broke-mode','messages-mode','registration-mode','debts-mode');document.body.classList.add('bros-join-mode');render();window.scrollTo(0,0);}
function render(){document.querySelector('#bros-join').innerHTML=`<div class="registration-top"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"><button data-bros="back">← ${stage==='choose'?t("Back","Quay lại","뒤로"):t("Change sign-up method","Đổi cách tham gia","가입 방법 변경")}</button></div><div class="bros-join-content"><img class="bros-join-mark" src="assets/debtfreelately-mark-clean.png" alt=""><p class="registration-eyebrow">${t("WELCOME, BROS","CHÀO MỪNG BROS","BROS에 오신 것을 환영합니다")}</p><h1>${stage==='choose'?t("How would you like to get started?","Bạn muốn bắt đầu thế nào?","어떻게 시작할까요?"):login?t("Welcome back.","Chào mừng bạn trở lại.","다시 오신 것을 환영합니다."):t("A nickname. A fresh start.","Một biệt danh. Một khởi đầu.","닉네임 하나로 새롭게 시작하세요.")}</h1><p class="bros-join-description">${stage==='choose'?t("Choose how to join and start supporting Broke members.","Chọn cách tham gia phù hợp với bạn và bắt đầu đồng hành cùng Broke.","가입 방법을 선택하고 Broke 회원과 함께하세요."):login?t("Sign in with your nickname and password.","Đăng nhập bằng biệt danh và mật khẩu của bạn.","닉네임과 비밀번호로 로그인하세요."):t("Create an account quickly to start browsing Broke stories.","Tạo tài khoản nhanh để vào tìm Broke ngay.","빠르게 계정을 만들어 Broke 이야기를 둘러보세요.")}</p>${stage==='choose'?`<div class="bros-join-options"><button data-bros="nickname"><span class="bros-option-icon">☆</span><small>${t("QUICK START","BẮT ĐẦU NHANH","빠른 시작")}</small><h2>${t("Nickname &amp; password","Biệt danh &amp; mật khẩu","닉네임과 비밀번호")}</h2><p>${t("Choose a unique nickname.","Chọn một tên riêng, không trùng với người khác.","다른 사람이 사용하지 않는 닉네임을 선택하세요.")}<br>${t("You can get started without an email address.","Không cần email để bắt đầu.","이메일 없이 시작할 수 있습니다.")}</p><strong>${t("Discover Broke stories →","Vào tìm Broke ngay →","Broke 이야기 둘러보기 →")}</strong></button><button data-bros="full"><span class="bros-option-icon">♙</span><small>${t("FULL REGISTRATION","ĐĂNG KÝ ĐẦY ĐỦ","정식 가입")}</small><h2>${t("Personal information","Thông tin cá nhân","개인 정보")}</h2><p>${t("Full name, gender, age, phone number and email.","Họ tên thật, giới tính, tuổi, điện thoại và email.","실명, 성별, 나이, 전화번호 및 이메일을 입력합니다.")}<br>${t("Verify your email with a confirmation code.","Xác minh email bằng mã xác nhận.","인증 코드로 이메일을 확인합니다.")}</p><strong>${t("Register a full account →","Đăng ký tài khoản đầy đủ →","정식 계정 가입 →")}</strong></button></div><p class="bros-join-footnote">${t("No one gets debt-free alone.","Không ai thoát nợ một mình.","함께라면 빚에서 벗어날 수 있습니다.")}</p>`:`<form id="bros-nickname-form" class="registration-card bros-nickname-form"><label for="bros-nickname">${login?t("Nickname","Biệt danh","닉네임"):t("Unique nickname","Biệt danh duy nhất","고유한 닉네임")}</label><input id="bros-nickname" name="nickname" autocomplete="username" minlength="3" maxlength="30" required placeholder="${t("Example: KindBros_2026","Ví dụ: KindBros_2026","예: KindBros_2026")}"><p class="registration-caption">${t("3–30 characters: letters, numbers, periods, hyphens or underscores. Case insensitive.","3–30 ký tự: chữ, số, dấu chấm, gạch ngang hoặc gạch dưới. Không phân biệt chữ hoa/thường.","3~30자. 문자, 숫자, 마침표, 하이픈 또는 밑줄을 사용할 수 있으며 대소문자를 구분하지 않습니다.")}</p><label for="bros-password">${t("Password","Mật khẩu","비밀번호")}</label><div class="bros-password-row"><input id="bros-password" name="password" type="password" autocomplete="${login?'current-password':'new-password'}" minlength="8" maxlength="128" required placeholder="${t("At least 8 characters","Ít nhất 8 ký tự","8자 이상")}"><button type="button" data-bros="password">${t("Show","Hiện","표시")}</button></div>${login?'':profilePhotoPicker()}<p class="form-error" role="alert" id="bros-nickname-error"></p><button class="registration-submit">${login?t("Sign in &amp; discover Broke","Đăng nhập &amp; tìm Broke","로그인하고 Broke 둘러보기"):t("Create an account &amp; discover Broke","Tạo tài khoản &amp; tìm Broke","계정을 만들고 Broke 둘러보기")} <span>→</span></button><p class="registration-caption bros-password-note">${t("Nickname accounts do not have a recovery email. Keep your password somewhere safe.","Tài khoản biệt danh chưa có email khôi phục. Hãy lưu mật khẩu ở nơi an toàn.","닉네임 계정에는 복구 이메일이 없습니다. 비밀번호를 안전한 곳에 보관하세요.")}</p><div class="registration-switch">${login?t("New here?","Chưa có tài khoản?","계정이 없으신가요?"):t("Already have a nickname?","Đã có biệt danh?","이미 닉네임이 있으신가요?")} <button type="button" data-bros="login">${login?t("Quick sign-up","Đăng ký nhanh","빠른 가입"):t("Sign in","Đăng nhập","로그인")}</button></div></form>`}</div>`;
const form=document.querySelector('#bros-nickname-form');const readPhoto=form&&!login?bindProfilePhoto(form):null;if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('.registration-submit'),error=document.querySelector('#bros-nickname-error');b.disabled=true;error.textContent='';try{const body=Object.fromEntries(new FormData(form));if(readPhoto)body.photo=await readPhoto();const response=await fetch('/api/auth/'+(login?'nickname-login':'nickname-signup'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||t("Could not create the account.","Không thể tạo tài khoản.","계정을 만들 수 없습니다."));document.body.classList.remove('bros-join-mode');form.reset();success(data.user);api.toast(login?t("Signed in. Welcome, Bros!","Đã đăng nhập. Chào mừng Bros!","로그인했습니다. Bros에 오신 것을 환영합니다!"):t("Account created. Let's find a story!","Tài khoản đã được tạo. Cùng tìm một câu chuyện nhé!","계정을 만들었습니다. 이제 이야기를 둘러보세요!"));}catch(err){error.textContent=translateError(err.message);b.disabled=false;}};
}

